package com.jnapanam.sportszone.membership.dto; import com.jnapanam.sportszone.membership.model.CustomerMembership; import java.time.*; import java.util.UUID;
public record CustomerMembershipResponse(UUID id,UUID userId,String customerName,String planCode,String planName,String status,LocalDate startDate,LocalDate endDate,Instant subscribedAt,Instant activatedAt,String reason,Instant paymentExpiresAt){public static CustomerMembershipResponse from(CustomerMembership m){return new CustomerMembershipResponse(m.getId(),m.getUser().getId(),m.getUser().getFullName(),m.getPlan().getCode(),m.getPlan().getName(),m.getStatus().name(),m.getStartDate(),m.getEndDate(),m.getSubscribedAt(),m.getActivatedAt(),m.getReason(),m.getPaymentExpiresAt());}}
